package com.coc.zkqcode.jar.ui

import android.graphics.BitmapFactory
import android.util.Base64
import androidx.compose.foundation.Image
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.asImageBitmap
import androidx.compose.ui.layout.ContentScale

// Background image embedded as Base64 to keep it within the jar module.
private const val BACKGROUND_BASE64 = ""

// Decodes the embedded Base64 background image and renders it full-bleed.
@Composable
fun BackgroundImage() {
    val bitmap = remember {
        val bytes = Base64.decode(BACKGROUND_BASE64, Base64.DEFAULT)
        BitmapFactory.decodeByteArray(bytes, 0, bytes.size).asImageBitmap()
    }
    Image(
        bitmap = bitmap,
        contentDescription = null,
        modifier = Modifier.fillMaxSize(),
        contentScale = ContentScale.Crop
    )
}